export function resolvePolicySettings(saved: Record<string, any> | null) {
  const current: Record<string, any> = { ...(saved || {}) };
  for (const kind of ['terms', 'refund'] as const) {
    const policy = suppliedPolicies[kind];
    // A new client-provided source replaces the previous placeholder version.
    if (current[kind + 'SourceHash'] !== policy.sha256) {
      current[kind] = policy.text;
      current[kind + 'Published'] = true;
      current[kind + 'SourceHash'] = policy.sha256;
    }
  }
  return current;
}
